            <small class="month-booking-state">{{ $cell['category']==='off'?'غير متاح للعمل':($cell['full']?'متاح — انتهى عدد الحجوزات':'متاح — جاري الحجز') }}</small>
            <div class="month-day-content">@if($cell['category']==='off')<span class="month-day-badge badge-off">{{ $cell['offLabel'] }}</span>@if($cell['count'])<strong>{{ $cell['count'] }} مواعيد مسجلة</strong>@endif<small>لا توجد أوقات متاحة للحجز</small>@else<strong>{{ $cell['count'] }} {{ $cell['count']===1?'موعد':'مواعيد' }}</strong>@if($cell['special'] && $cell['category']==='partial')<small>حتى <span class="font-num">{{ $cell['closingTime'] }}</span></small>@else<small>{{ $cell['full']?'غير متاح':$cell['remaining'].' خانات متاحة' }}</small>@endif @endif</div>
            @if($cell['today'])<span class="month-today-label">اليوم</span>@endif
